const button=$('createstairs');button.innerHTML='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 20h5v-6h5V8h5V3h3"/></svg><span>Stair path</span><kbd>S</kbd>';button.title='S · Click the stair route; Shift: 45°; Enter: finish';button.onclick=()=>setTool(tool==='stair-route'?'select':'stair-route');const preset=document.createElement('button');preset.id='tool-stair-presets';preset.textContent='Stair presets';preset.title='Straight, switchback and spiral floor stacks';preset.onclick=()=>openStairCreation();$('tool-edge-steps').after(preset);

